AssistantMessageToolRequest(name='create', tool_call_id='tooluse_W6jzAgnz979Ns4cHhasA7R', arguments={'file_text': '/* === Reset & base === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-input:       #12141e;
  --border:         #2e3148;
  --border-focus:   #6c8aff;
  --border-error:   #ff5c5c;
  --text-primary:   #e8eaf6;
  --text-secondary: #9198b5;
  --text-placeholder: #555c78;
  --accent:         #6c8aff;
  --accent-hover:   #8aa4ff;
  --error:          #ff7070;
  --error-bg:       #2a1a1a;
  --success:        #4caf7d;
  --success-bg:     #0f2a1e;
  --required-star:  #ff7070;
}

html { font-size: 16px; }

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* === Skip link === */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 0;
  padding: 0.75rem 1.25rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  border-radius: 0 0 0.5rem 0;
}
.skip-link:focus {
  top: 0;
  outline: 3px solid #fff;
  outline-offset: 2px;
}

/* === Layout === */
header {
  background: var(--bg-card);
  border-bottom: 1px solid var(--border);
  padding: 1.25rem 1.5rem;
}

header h1 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.01em;
}

main {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 3rem 1.5rem;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 1rem;
  padding: 2.5rem;
  width: 100%;
  max-width: 520px;
}

.card-heading {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.375rem;
  color: var(--text-primary);
}

.card-subheading {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 2rem;
}

/* === Required legend === */
.required-legend {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}
.required-legend .star {
  color: var(--required-star);
  font-weight: 700;
  margin-right: 0.2em;
}

/* === Form fields === */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.5rem;
}

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.required-star {
  color: var(--required-star);
  font-size: 1rem;
  line-height: 1;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  background: var(--bg-input);
  border: 1.5px solid var(--border);
  border-radius: 0.5rem;
  color: var(--text-primary);
  font-size: 1rem;
  padding: 0.6875rem 0.875rem;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  width: 100%;
  appearance: none;
}

input::placeholder {
  color: var(--text-placeholder);
}

input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 138, 255, 0.25);
}

input[aria-invalid="true"] {
  border-color: var(--border-error);
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 92, 92, 0.25);
}

/* === Help and error text === */
.field-help {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.45;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--error);
  line-height: 1.45;
  display: none;
  align-items: flex-start;
  gap: 0.3em;
}

.field-error.visible {
  display: flex;
}

.field-error::before {
  content: "⚠";
  flex-shrink: 0;
  margin-top: 0.05em;
}

/* === Submit === */
.btn-submit {
  width: 100%;
  padding: 0.8125rem 1.25rem;
  background: var(--accent);
  border: none;
  border-radius: 0.5rem;
  color: #fff;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: background-color 0.15s ease, box-shadow 0.15s ease;
  margin-top: 0.5rem;
}

.btn-submit:hover {
  background: var(--accent-hover);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

.btn-submit:active {
  opacity: 0.9;
}

/* === Status banner === */
.status-banner {
  border-radius: 0.5rem;
  padding: 0.875rem 1rem;
  font-size: 0.9375rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
  display: none;
}

.status-banner.success {
  background: var(--success-bg);
  border: 1.5px solid var(--success);
  color: var(--success);
  display: block;
}

.status-banner.error-summary {
  background: var(--error-bg);
  border: 1.5px solid var(--border-error);
  color: var(--error);
  display: block;
}

/* === Footer === */
footer {
  text-align: center;
  padding: 1.5rem;
  color: var(--text-secondary);
  font-size: 0.8125rem;
  border-top: 1px solid var(--border);
}

/* === Forced colors (high contrast) === */
@media (forced-colors: active) {
  input:focus,
  .btn-submit:focus-visible,
  .skip-link:focus {
    outline: 3px solid ButtonText;
  }
  input[aria-invalid="true"] { border-color: LinkText; }
  .field-error { color: LinkText; }
  .btn-submit { forced-color-adjust: none; background: Highlight; color: HighlightText; }
}

/* === Reflow / narrow viewports === */
@media (max-width: 400px) {
  .card { padding: 1.5rem 1.25rem; }
  main { padding: 1.5rem 0.75rem; }
}

/* === Reduced motion === */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}
