        // RFC-5322 simplified pattern
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
          return 'Error: Enter a valid email address, like name@example.com.';
        }
        return null;
      },
    },
    phone: {
      required: false,
      validate(value) {
        if (!value.trim()) return null; // optional
        // Allow digits, spaces, hyphens, parentheses, plus sign; 7–15 digits
        const digits = value.replace(/\D/g, '');
        if (digits.length < 7 || digits.length > 15) {
          return 'Error: Enter a valid phone number, like +1 (555) 000-0000.';
        }
        return null;
      },
    },
  };

  // ── Field descriptors ─────────────────────────────────────────────────────
  const FIELDS = [
    { key: 'fullName', inputId: 'full-name', errorId: 'full-name-error' },
    { key: 'email',    inputId: 'email',     errorId: 'email-error'     },
    { key: 'phone',    inputId: 'phone',     errorId: 'phone-error'     },
  ];

  // ── Helpers ───────────────────────────────────────────────────────────────
  function setError(field, message) {
    const input = document.getElementById(field.inputId);
    const errorEl = document.getElementById(field.errorId);
    if (!input || !errorEl) return;

    if (message) {
      input.setAttribute('aria-invalid', 'true');
      errorEl.textContent = message;
      errorEl.classList.add('visible');
    } else {
      input.setAttribute('aria-invalid', 'false');
      errorEl.textContent = '';
      errorEl.classList.remove('visible');
    }
  }

  function clearError(field) {
    setError(field, null);
  }

  function validateField(field) {
    const input = document.getElementById(field.inputId);
    if (!input) return null;
    return RULES[field.key].validate(input.value);
  }

  // ── Live (on-blur) validation ─────────────────────────────────────────────
  function attachBlurValidation() {
    FIELDS.forEach((field) => {
      const input = document.getElementById(field.inputId);
      if (!input) return;

      input.addEventListener('blur', () => {
        const error = validateField(field);
        setError(field, error);
      });

      // Clear error while the user corrects the field
      input.addEventListener('input', () => {
        if (input.getAttribute('aria-invalid') === 'true') {
          const error = validateField(field);
          setError(field, error);
        }
      });
    });
  }

  // ── Submit handler ────────────────────────────────────────────────────────
  function handleSubmit(e) {
    e.preventDefault();

    const statusEl    = document.getElementById('form-status');
    const successEl   = document.getElementById('form-success');

    // Validate all fields
    const errors = FIELDS.map((field) => {
      const message = validateField(field);
      setError(field, message);
      return { field, message };
    }).filter((r) => r.message !== null);

    if (errors.length > 0) {
      // Move focus to the first invalid field
      const firstInvalidId = errors[0].field.inputId;
      const firstInvalid = document.getElementById(firstInvalidId);
      if (firstInvalid) firstInvalid.focus();

      // Announce error count to AT via role="alert"
      statusEl.textContent = '';
      // Small delay lets the DOM settle before the alert fires
      requestAnimationFrame(() => {
        statusEl.textContent =
          `${errors.length} error${errors.length > 1 ? 's' : ''} found. Please correct the highlighted fields.`;
      });

      // Hide success banner if previously shown
      successEl.classList.remove('success');
      successEl.textContent = '';
      return;
    }

    // ── No errors: simulate submission ────────────────────────────────────
    statusEl.textContent = '';

    // Show success banner
    successEl.textContent = '✓ Your message has been sent. We'll be in touch soon.';
    successEl.classList.add('success');

    // Reset form
    e.target.reset();
    FIELDS.forEach(clearError);

    // Move focus to the success banner so keyboard/AT users see confirmation
    successEl.setAttribute('tabindex', '-1');
    successEl.focus();
  }

  // ── Init ──────────────────────────────────────────────────────────────────
  document.addEventListener('DOMContentLoaded', () => {
    attachBlurValidation();

    const form = document.getElementById('contact-form');
    if (form) form.addEventListener('submit', handleSubmit);
  });
})();
