.skip-link {
  position: absolute;
  top: -9999px;
  left: 0;
  padding: 0.75rem 1.25rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  border-radius: 0 0 0.5rem 0;
}
.skip-link:focus {
  top: 0;
  outline: 3px solid #fff;
  outline-offset: 2px;
}

/* === Layout === */
header {
  background: var(--bg-card);
  border-bottom: 1px solid var(--border);
  padding: 1.25rem 1.5rem;
}

header h1 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.01em;
}

main {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 3rem 1.5rem;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 1rem;
  padding: 2.5rem;
  width: 100%;
  max-width: 520px;
}

.card-heading {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.375rem;
  color: var(--text-primary);
}

.card-subheading {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 2rem;
}

/* === Required legend === */
.required-legend {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}
.required-legend .star {
  color: var(--required-star);
  font-weight: 700;
  margin-right: 0.2em;
}

/* === Form fields === */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.5rem;
}

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.required-star {
  color: var(--required-star);
  font-size: 1rem;
  line-height: 1;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  background: var(--bg-input);
  border: 1.5px solid var(--border);
  border-radius: 0.5rem;
  color: var(--text-primary);
  font-size: 1rem;
  padding: 0.6875rem 0.875rem;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  width: 100%;
  appearance: none;
}

input::placeholder {
  color: var(--text-placeholder);
}

input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 138, 255, 0.25);
}

input[aria-invalid="true"] {
  border-color: var(--border-error);
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 92, 92, 0.25);
}

/* === Help and error text === */
.field-help {
